"""
    Function that prints the subnet related details- Network, Broadcast, Host IP range and number of host addresses
    :param addr: IP address
    :param mask: subnet mask
    :return: result dictionary containing the details
    """
def ipv4_subnet_details(addr: Any, mask: Any) -> object {
    network_address = [];
    broadcast_address = [];
    num_ips = 1;
    wildcard_mask = {
        "255": "0",
        "254": "1",
        "252": "3",
        "248": "7",
        "240": "15",
        "224": "31",
        "192": "63",
        "128": "127",
        "0": "255"
    };
    for (_octet, _mask) in zip(addr.split("."), mask.split(".")) {
        network_address.append(str((int(_octet) & int(_mask))));
        broadcast_address.append(str((int(_octet) | int(wildcard_mask[_mask]))));
        num_ips *= int(wildcard_mask[_mask]) + 1;
    }
    host_address_low = network_address[:3] + [str((int(network_address[3]) + 1))];
    host_address_high = broadcast_address[:3] + [str((int(broadcast_address[3]) - 1))];
    host_ips = num_ips - 2;
    result = `dict();
    result["nw_addr"] = ".".join(network_address);
    result["bc_addr"] = ".".join(broadcast_address);
    result["host_addr_range"] = f"{'.'.join(host_address_low)} to {'.'.join(
        host_address_high
    )}";
    result["usable_ips"] = host_ips;
    return result;
}
